import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # If opponent has been fully cooperative so far, mostly cooperate,
    # but exploit a bit more near the end. This is strong against unconditional
    # cooperators while remaining safe against reciprocal opponents.
    if opp_d == 0:
        if n >= 88:
            return 'D' if rng.random() < 0.85 else 'C'
        if n >= 60:
            return 'D' if rng.random() < 0.22 else 'C'
        return 'C'

    # Opponent looks consistently defective: defend, but keep occasional
    # probes so we can recover if they switch.
    if opp_d >= opp_c + 3 or (n >= 8 and opp_c <= 1):
        if n < 4:
            return 'D'
        if opp[-1] == 'C':
            return 'C' if rng.random() < 0.65 else 'D'
        if rng.random() < 0.10:
            return 'C'
        return 'D'

    # Main reciprocal regime.
    last_me, last_opp = history[-1]

    # Break mutual defection spirals.
    recent = history[-8:]
    rec_opp_d = sum(1 for x in recent if x[1] == 'D')
    rec_me_d = sum(1 for x in recent if x[0] == 'D')
    rec_cc = sum(1 for x in recent if x[0] == 'C' and x[1] == 'C')
    if rec_opp_d >= 5 and rec_me_d >= 4:
        if rng.random() < 0.75:
            return 'C'

    # Reward cooperation with cooperation, but exploit late.
    if last_opp == 'C':
        if n > 90:
            if rng.random() < 0.35:
                return 'D'
        elif n > 75:
            if rng.random() < 0.10:
                return 'D'
        return 'C'

    # Opponent just defected. Usually retaliate, with measured forgiveness.
    if n >= 6:
        cc = cd = dc = dd = 0
        for a, b in history[-6:]:
            if a == 'C' and b == 'C':
                cc += 1
            elif a == 'C' and b == 'D':
                cd += 1
            elif a == 'D' and b == 'C':
                dc += 1
            else:
                dd += 1

        # If exploiting cooperators has been profitable, continue more often.
        if dc >= 2 and cc >= 1:
            if rng.random() < 0.55:
                return 'D'

        # If mutual defection dominates, try to restart cooperation.
        if dd >= 3 and cc == 0:
            if rng.random() < 0.70:
                return 'C'

    # Tit-for-tat with small forgiveness.
    if rng.random() < 0.10:
        return 'C'
    return 'D'
